import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';

export const READING = 'reading';
export const FINISHED = 'finished';

/**
 * A book store backed by a single JSON file.
 *
 * The whole file is read on load and rewritten on every change. That is fine
 * for a personal reading list and it keeps the file human-editable. Writes go
 * through a promise chain so two overlapping requests can't interleave, and
 * land via a temp file + rename so a crash mid-write can't truncate the list.
 */
export class BookStore {
  #path;
  #books = [];
  #writing = Promise.resolve();

  constructor(path) {
    this.#path = path;
  }

  async load() {
    try {
      const raw = await readFile(this.#path, 'utf8');
      const parsed = JSON.parse(raw);
      this.#books = Array.isArray(parsed) ? parsed.map(normalize) : [];
    } catch (err) {
      if (err.code !== 'ENOENT') throw err;
      this.#books = [];
    }
    return this;
  }

  /** Books still being read, most recently added first. */
  reading() {
    return this.#books
      .filter((b) => b.status === READING)
      .sort((a, b) => cmpDesc(a.addedAt, b.addedAt));
  }

  /** Finished books, most recently finished first. */
  finished() {
    return this.#books
      .filter((b) => b.status === FINISHED)
      .sort((a, b) => cmpDesc(a.finishedAt ?? a.addedAt, b.finishedAt ?? b.addedAt));
  }

  get(id) {
    return this.#books.find((b) => b.id === id);
  }

  async add({ title, author, notes }) {
    const book = {
      id: randomUUID(),
      title: title.trim(),
      author: (author ?? '').trim(),
      notes: (notes ?? '').trim(),
      status: READING,
      addedAt: new Date().toISOString(),
      finishedAt: null,
    };
    this.#books.push(book);
    await this.#persist();
    return book;
  }

  /** Mark a book finished. Returns the book, or undefined if the id is unknown. */
  async finish(id) {
    const book = this.get(id);
    if (!book) return undefined;
    if (book.status !== FINISHED) {
      book.status = FINISHED;
      book.finishedAt = new Date().toISOString();
      await this.#persist();
    }
    return book;
  }

  /** Move a finished book back to the reading list — for mis-clicks. */
  async reopen(id) {
    const book = this.get(id);
    if (!book) return undefined;
    if (book.status !== READING) {
      book.status = READING;
      book.finishedAt = null;
      await this.#persist();
    }
    return book;
  }

  async setNotes(id, notes) {
    const book = this.get(id);
    if (!book) return undefined;
    book.notes = (notes ?? '').trim();
    await this.#persist();
    return book;
  }

  #persist() {
    // Serialize now, so the queued write saves this snapshot rather than
    // whatever the array looks like once the turn comes around.
    const json = JSON.stringify(this.#books, null, 2);
    this.#writing = this.#writing.then(
      () => writeAtomic(this.#path, json),
      () => writeAtomic(this.#path, json),
    );
    return this.#writing;
  }
}

async function writeAtomic(path, contents) {
  await mkdir(dirname(path), { recursive: true });
  const tmp = `${path}.${process.pid}.tmp`;
  await writeFile(tmp, contents, 'utf8');
  await rename(tmp, path);
}

/** Fill in anything a hand-edited or older JSON file might be missing. */
function normalize(book) {
  return {
    id: book.id ?? randomUUID(),
    title: book.title ?? 'Untitled',
    author: book.author ?? '',
    notes: book.notes ?? '',
    status: book.status === FINISHED ? FINISHED : READING,
    addedAt: book.addedAt ?? new Date(0).toISOString(),
    finishedAt: book.finishedAt ?? null,
  };
}

function cmpDesc(a, b) {
  return String(b).localeCompare(String(a));
}

