import { FINISHED } from './store.js';

export function escapeHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function page(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<link rel="stylesheet" href="/style.css">
</head>
<body>
<main>
${body}
</main>
</body>
</html>
`;
}

function formatDate(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  return d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
}

function bookListItem(book) {
  const author = book.author ? `<span class="author">${escapeHtml(book.author)}</span>` : '';
  const when =
    book.status === FINISHED
      ? `<span class="when">finished ${escapeHtml(formatDate(book.finishedAt))}</span>`
      : `<span class="when">added ${escapeHtml(formatDate(book.addedAt))}</span>`;
  const finishButton =
    book.status === FINISHED
      ? ''
      : `<form method="post" action="/books/${encodeURIComponent(book.id)}/finish">
      <button type="submit" class="secondary">Mark finished</button>
    </form>`;
  return `<li>
  <div class="row">
    <div>
      <a class="title" href="/books/${encodeURIComponent(book.id)}">${escapeHtml(book.title)}</a>
      ${author}
      ${when}
    </div>
    ${finishButton}
  </div>
</li>`;
}

function bookList(books, emptyMessage) {
  if (books.length === 0) return `<p class="empty">${escapeHtml(emptyMessage)}</p>`;
  return `<ul class="books">\n${books.map(bookListItem).join('\n')}\n</ul>`;
}

export function renderHome({ reading, finished, error, form }) {
  const draft = form ?? {};
  const body = `
<h1>Bookshelf</h1>

<section>
  <h2>Currently reading <span class="count">${reading.length}</span></h2>
  ${bookList(reading, 'Nothing on the go right now. Add a book below.')}
</section>

<section>
  <h2>Finished <span class="count">${finished.length}</span></h2>
  ${bookList(finished, 'No finished books yet.')}
</section>

<section class="add">
  <h2>Add a book</h2>
  ${error ? `<p class="error">${escapeHtml(error)}</p>` : ''}
  <form method="post" action="/books">
    <label>
      Title
      <input name="title" required autocomplete="off" value="${escapeHtml(draft.title)}">
    </label>
    <label>
      Author
      <input name="author" autocomplete="off" value="${escapeHtml(draft.author)}">
    </label>
    <label>
      Notes <span class="hint">optional</span>
      <textarea name="notes" rows="3">${escapeHtml(draft.notes)}</textarea>
    </label>
    <button type="submit">Add book</button>
  </form>
</section>
`;
  return page('Bookshelf', body);
}

export function renderBook(book, { saved } = {}) {
  const id = encodeURIComponent(book.id);
  const isFinished = book.status === FINISHED;
  const statusLine = isFinished
    ? `Finished ${escapeHtml(formatDate(book.finishedAt))}`
    : `Reading since ${escapeHtml(formatDate(book.addedAt))}`;
  const statusForm = isFinished
    ? `<form method="post" action="/books/${id}/reopen">
      <button type="submit" class="secondary">Move back to reading</button>
    </form>`
    : `<form method="post" action="/books/${id}/finish">
      <button type="submit">Mark finished</button>
    </form>`;

  const body = `
<p class="back"><a href="/">&larr; Bookshelf</a></p>

<article>
  <h1>${escapeHtml(book.title)}</h1>
  <p class="byline">${book.author ? escapeHtml(book.author) : '<span class="empty">Unknown author</span>'}</p>
  <p class="status ${isFinished ? 'is-finished' : 'is-reading'}">${statusLine}</p>
  ${statusForm}

  <section class="notes">
    <h2>Notes</h2>
    ${saved ? '<p class="saved">Notes saved.</p>' : ''}
    <form method="post" action="/books/${id}/notes">
      <textarea name="notes" rows="8" placeholder="What did you think?">${escapeHtml(book.notes)}</textarea>
      <button type="submit" class="secondary">Save notes</button>
    </form>
  </section>
</article>
`;
  return page(book.title, body);
}

export function renderNotFound() {
  return page(
    'Not found',
    `
<h1>Not found</h1>
<p>There's no book at this address. It may have been removed, or the link may be wrong.</p>
<p class="back"><a href="/">&larr; Bookshelf</a></p>
`,
  );
}

