export const CSS = `:root {
  color-scheme: light dark;
  --bg: #fbfaf7;
  --fg: #1c1a17;
  --muted: #6b6560;
  --line: #e2ddd4;
  --card: #ffffff;
  --accent: #7a4a2b;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #16151a;
    --fg: #ece9e4;
    --muted: #9a938c;
    --line: #322f36;
    --card: #1e1d23;
    --accent: #d9a273;
  }
}

* { box-sizing: border-box; }

body {
  margin: 0;
  padding: 2.5rem 1.25rem 4rem;
  background: var(--bg);
  color: var(--fg);
  font: 16px/1.55 ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

main { max-width: 40rem; margin: 0 auto; }

h1 { font-size: 1.9rem; margin: 0 0 1.5rem; letter-spacing: -0.02em; }
h2 { font-size: 1rem; text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); margin: 0 0 0.75rem; }

section { margin-bottom: 2.5rem; }

.count {
  display: inline-block;
  min-width: 1.4em;
  padding: 0 0.35em;
  border-radius: 999px;
  background: var(--line);
  color: var(--muted);
  font-size: 0.8rem;
  text-align: center;
  letter-spacing: 0;
}

ul.books { list-style: none; margin: 0; padding: 0; }

ul.books li {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 0.6rem;
  padding: 0.85rem 1rem;
  margin-bottom: 0.6rem;
}

.row { display: flex; align-items: center; justify-content: space-between; gap: 1rem; }
.row > div:first-child { display: flex; flex-direction: column; min-width: 0; }
.row form { margin: 0; flex: none; }

a { color: var(--accent); }

a.title {
  font-weight: 600;
  font-size: 1.05rem;
  text-decoration: none;
  color: var(--fg);
}
a.title:hover { color: var(--accent); text-decoration: underline; }

.author { color: var(--muted); font-size: 0.92rem; }
.when { color: var(--muted); font-size: 0.78rem; margin-top: 0.15rem; }

.empty { color: var(--muted); font-style: italic; margin: 0; }

form { display: flex; flex-direction: column; gap: 0.9rem; }
label { display: flex; flex-direction: column; gap: 0.3rem; font-size: 0.85rem; color: var(--muted); }
.hint { color: var(--muted); font-weight: 400; font-size: 0.78rem; }

input, textarea {
  font: inherit;
  color: var(--fg);
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 0.45rem;
  padding: 0.55rem 0.7rem;
  width: 100%;
}
textarea { resize: vertical; }
input:focus, textarea:focus { outline: 2px solid var(--accent); outline-offset: 1px; }

button {
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  align-self: flex-start;
  padding: 0.5rem 0.95rem;
  border: 1px solid var(--accent);
  border-radius: 0.45rem;
  background: var(--accent);
  color: var(--bg);
}
button.secondary { background: transparent; color: var(--accent); }
button:hover { filter: brightness(1.08); }

.error {
  background: #fdecea;
  color: #8a1c12;
  border: 1px solid #f3c1bb;
  border-radius: 0.45rem;
  padding: 0.6rem 0.8rem;
  margin: 0 0 0.9rem;
}
@media (prefers-color-scheme: dark) {
  .error { background: #3a1c19; color: #f4b8b0; border-color: #5c2c26; }
}

.saved { color: var(--muted); font-size: 0.85rem; margin: 0 0 0.6rem; }

.back { font-size: 0.85rem; margin: 0 0 1.5rem; }
.back a { text-decoration: none; }
.back a:hover { text-decoration: underline; }

article h1 { margin-bottom: 0.35rem; }
.byline { margin: 0 0 0.75rem; color: var(--muted); font-size: 1.05rem; }

.status {
  display: inline-block;
  font-size: 0.78rem;
  padding: 0.15rem 0.55rem;
  border-radius: 999px;
  border: 1px solid var(--line);
  color: var(--muted);
  margin: 0 0 1.25rem;
}
.status.is-finished { border-color: var(--accent); color: var(--accent); }

.notes { margin-top: 2.5rem; }
`;

