import { CSS } from './styles.js';
import { renderBook, renderHome, renderNotFound } from './views.js';

/** Plenty for a title, an author and a page of notes; stops a runaway body. */
const MAX_BODY_BYTES = 64 * 1024;

/**
 * Build the request handler. Pages are rendered server-side so every book has
 * a real URL that can be pasted to someone else, and writes use
 * POST-then-redirect so a refresh doesn't repeat the action.
 */
export function createApp(store) {
  return async function handle(req, res) {
    try {
      await route(store, req, res);
    } catch (err) {
      console.error('Request failed:', err);
      if (!res.headersSent) send(res, 500, 'text/plain; charset=utf-8', 'Something went wrong.');
      else res.end();
    }
  };
}

async function route(store, req, res) {
  const url = new URL(req.url, 'http://localhost');
  const path = url.pathname.replace(/\/+$/, '') || '/';
  const method = req.method === 'HEAD' ? 'GET' : req.method;

  if (method === 'GET' && path === '/') {
    return html(res, 200, renderHome({ reading: store.reading(), finished: store.finished() }));
  }

  if (method === 'GET' && path === '/style.css') {
    return send(res, 200, 'text/css; charset=utf-8', CSS);
  }

  if (method === 'POST' && path === '/books') {
    const form = await readForm(req);
    const draft = {
      title: (form.get('title') ?? '').trim(),
      author: (form.get('author') ?? '').trim(),
      notes: (form.get('notes') ?? '').trim(),
    };
    if (!draft.title) {
      return html(
        res,
        400,
        renderHome({
          reading: store.reading(),
          finished: store.finished(),
          error: 'A book needs a title.',
          form: draft,
        }),
      );
    }
    const book = await store.add(draft);
    return redirect(res, `/books/${encodeURIComponent(book.id)}`);
  }

  const bookMatch = path.match(/^\/books\/([^/]+)(?:\/(finish|reopen|notes))?$/);
  if (bookMatch) {
    const id = safeDecode(bookMatch[1]);
    const action = bookMatch[2];

    if (method === 'GET' && !action) {
      const book = store.get(id);
      if (!book) return html(res, 404, renderNotFound());
      return html(res, 200, renderBook(book, { saved: url.searchParams.has('saved') }));
    }

    if (method === 'POST' && action) {
      const target = `/books/${encodeURIComponent(id)}`;
      if (action === 'finish') {
        if (!(await store.finish(id))) return html(res, 404, renderNotFound());
        // Finishing is usually done from the home list, so go back there.
        return redirect(res, referrerIsHome(req) ? '/' : target);
      }
      if (action === 'reopen') {
        if (!(await store.reopen(id))) return html(res, 404, renderNotFound());
        return redirect(res, referrerIsHome(req) ? '/' : target);
      }
      const form = await readForm(req);
      if (!(await store.setNotes(id, form.get('notes')))) return html(res, 404, renderNotFound());
      return redirect(res, `${target}?saved=1`);
    }

    return send(res, 405, 'text/plain; charset=utf-8', 'Method not allowed');
  }

  return html(res, 404, renderNotFound());
}

function referrerIsHome(req) {
  const referer = req.headers?.referer;
  if (!referer) return false;
  try {
    return new URL(referer, 'http://localhost').pathname.replace(/\/+$/, '') === '';
  } catch {
    return false;
  }
}

function safeDecode(value) {
  try {
    return decodeURIComponent(value);
  } catch {
    return value;
  }
}

function readForm(req) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on('data', (chunk) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        reject(new Error('Form body too large'));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(new URLSearchParams(Buffer.concat(chunks).toString('utf8'))));
    req.on('error', reject);
  });
}

function send(res, status, contentType, body) {
  res.writeHead(status, {
    'Content-Type': contentType,
    'Content-Length': Buffer.byteLength(body),
    'Cache-Control': 'no-store',
  });
  res.end(body);
}

function html(res, status, body) {
  send(res, status, 'text/html; charset=utf-8', body);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location, 'Content-Length': '0' });
  res.end();
}

