import { mkdtemp, readFile, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { beforeEach, describe, expect, it } from 'vitest';

import { BookStore, FINISHED, READING } from '../src/store.js';

let file;

beforeEach(async () => {
  const dir = await mkdtemp(join(tmpdir(), 'bookshelf-'));
  file = join(dir, 'books.json');
});

async function freshStore() {
  return new BookStore(file).load();
}

describe('BookStore', () => {
  it('starts empty when the file does not exist', async () => {
    const store = await freshStore();
    expect(store.reading()).toEqual([]);
    expect(store.finished()).toEqual([]);
  });

  it('adds a book as currently reading', async () => {
    const store = await freshStore();
    const book = await store.add({ title: 'Piranesi', author: 'Susanna Clarke' });

    expect(book.status).toBe(READING);
    expect(store.reading().map((b) => b.title)).toEqual(['Piranesi']);
    expect(store.finished()).toEqual([]);
  });

  it('trims whitespace and defaults optional fields', async () => {
    const store = await freshStore();
    const book = await store.add({ title: '  Dune  ' });

    expect(book.title).toBe('Dune');
    expect(book.author).toBe('');
    expect(book.notes).toBe('');
  });

  it('survives a restart', async () => {
    const first = await freshStore();
    await first.add({ title: 'Dune', author: 'Frank Herbert', notes: 'Spice.' });

    const second = await freshStore();
    const [book] = second.reading();
    expect(book.title).toBe('Dune');
    expect(book.author).toBe('Frank Herbert');
    expect(book.notes).toBe('Spice.');
  });

  it('moves a book from reading to finished', async () => {
    const store = await freshStore();
    const book = await store.add({ title: 'Dune' });

    const finished = await store.finish(book.id);
    expect(finished.status).toBe(FINISHED);
    expect(finished.finishedAt).toBeTruthy();
    expect(store.reading()).toEqual([]);
    expect(store.finished().map((b) => b.id)).toEqual([book.id]);
  });

  it('keeps the original finish time when finished twice', async () => {
    const store = await freshStore();
    const book = await store.add({ title: 'Dune' });

    const first = await store.finish(book.id);
    const when = first.finishedAt;
    const second = await store.finish(book.id);

    expect(second.finishedAt).toBe(when);
  });

  it('can move a finished book back to reading', async () => {
    const store = await freshStore();
    const book = await store.add({ title: 'Dune' });
    await store.finish(book.id);

    const reopened = await store.reopen(book.id);
    expect(reopened.status).toBe(READING);
    expect(reopened.finishedAt).toBeNull();
    expect(store.finished()).toEqual([]);
  });

  it('returns undefined for unknown ids', async () => {
    const store = await freshStore();
    expect(store.get('nope')).toBeUndefined();
    expect(await store.finish('nope')).toBeUndefined();
    expect(await store.reopen('nope')).toBeUndefined();
    expect(await store.setNotes('nope', 'hi')).toBeUndefined();
  });

  it('saves notes', async () => {
    const store = await freshStore();
    const book = await store.add({ title: 'Dune' });
    await store.setNotes(book.id, '  Worth the reread.  ');

    const reloaded = await freshStore();
    expect(reloaded.get(book.id).notes).toBe('Worth the reread.');
  });

  it('lists newest additions first and most recently finished first', async () => {
    const store = await freshStore();
    const a = await store.add({ title: 'A' });
    const b = await store.add({ title: 'B' });
    const c = await store.add({ title: 'C' });

    // addedAt can share a millisecond, so pin the ordering explicitly.
    a.addedAt = '2024-01-01T00:00:00.000Z';
    b.addedAt = '2024-02-01T00:00:00.000Z';
    c.addedAt = '2024-03-01T00:00:00.000Z';
    expect(store.reading().map((x) => x.title)).toEqual(['C', 'B', 'A']);

    await store.finish(a.id);
    await store.finish(b.id);
    a.finishedAt = '2024-04-01T00:00:00.000Z';
    b.finishedAt = '2024-05-01T00:00:00.000Z';
    expect(store.finished().map((x) => x.title)).toEqual(['B', 'A']);
  });

  it('keeps concurrent writes consistent on disk', async () => {
    const store = await freshStore();
    await Promise.all(
      Array.from({ length: 10 }, (_, i) => store.add({ title: `Book ${i}` })),
    );

    const onDisk = JSON.parse(await readFile(file, 'utf8'));
    expect(onDisk).toHaveLength(10);
    expect(new Set(onDisk.map((b) => b.id)).size).toBe(10);
  });

  it('repairs a hand-edited file with missing fields', async () => {
    await writeFile(file, JSON.stringify([{ id: 'x1', title: 'Handwritten' }]), 'utf8');
    const store = await freshStore();

    const book = store.get('x1');
    expect(book.status).toBe(READING);
    expect(book.author).toBe('');
    expect(book.notes).toBe('');
    expect(store.reading()).toHaveLength(1);
  });

  it('ignores a file that is not an array', async () => {
    await writeFile(file, JSON.stringify({ nope: true }), 'utf8');
    const store = await freshStore();
    expect(store.reading()).toEqual([]);
  });
});

