beforeEach(async () => {
  const dir = await mkdtemp(join(tmpdir(), 'bookshelf-app-'));
  store = await new BookStore(join(dir, 'books.json')).load();
  server = createServer(createApp(store));
  await new Promise((r) => server.listen(0, '127.0.0.1', r));
  base = `http://127.0.0.1:${server.address().port}`;
});

afterEach(async () => {
  await new Promise((r) => server.close(r));
});

/** POST a form without following the redirect, the way a test wants it. */
function postForm(path, fields, headers = {}) {
  return fetch(`${base}${path}`, {
    method: 'POST',
    redirect: 'manual',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', ...headers },
    body: new URLSearchParams(fields),
  });
}

async function addBook(fields) {
  const res = await postForm('/books', fields);
  expect(res.status).toBe(303);
  return res.headers.get('location');
}

describe('home page', () => {
  it('shows both sections and the add form', async () => {
    const body = await (await fetch(base)).text();
    expect(body).toContain('Currently reading');
    expect(body).toContain('Finished');
    expect(body).toContain('action="/books"');
  });

  it('lists reading and finished books separately', async () => {
    const readingUrl = await addBook({ title: 'Piranesi', author: 'Susanna Clarke' });
    const finishedUrl = await addBook({ title: 'Dune' });
    await postForm(`${new URL(finishedUrl, base).pathname}/finish`, {});

    const body = await (await fetch(base)).text();
    const readingSection = body.slice(
      body.indexOf('Currently reading'),
      body.indexOf('Finished'),
    );
    const finishedSection = body.slice(body.indexOf('Finished'), body.indexOf('Add a book'));

    expect(readingSection).toContain('Piranesi');
    expect(readingSection).not.toContain('Dune');
    expect(finishedSection).toContain('Dune');
    expect(readingUrl).toMatch(/^\/books\//);
  });

  it('serves the stylesheet', async () => {
    const res = await fetch(`${base}/style.css`);
    expect(res.status).toBe(200);
    expect(res.headers.get('content-type')).toContain('text/css');
  });
});

describe('adding a book', () => {
  it('redirects to the new book page', async () => {
    const location = await addBook({ title: 'Dune', author: 'Frank Herbert' });
    const detail = await (await fetch(`${base}${location}`)).text();
    expect(detail).toContain('Dune');
    expect(detail).toContain('Frank Herbert');
  });

  it('rejects a book with no title and keeps what was typed', async () => {
    const res = await postForm('/books', { title: '   ', author: 'Nobody' });
    expect(res.status).toBe(400);

    const body = await res.text();
    expect(body).toContain('A book needs a title.');
    expect(body).toContain('value="Nobody"');
    expect(store.reading()).toEqual([]);
  });
});

describe('book page', () => {
  it('shows title, author and notes at a shareable URL', async () => {
    const location = await addBook({
      title: 'Piranesi',
      author: 'Susanna Clarke',
      notes: 'The House is the world.',
    });

    // A cold request with no session or cookie — what a recipient of the link gets.
    const res = await fetch(`${base}${location}`);
    expect(res.status).toBe(200);

    const body = await res.text();
    expect(body).toContain('Piranesi');
    expect(body).toContain('Susanna Clarke');
    expect(body).toContain('The House is the world.');
  });

  it('marks a book finished from its own page and offers to undo', async () => {
    const location = await addBook({ title: 'Dune' });
    const path = new URL(location, base).pathname;

    const res = await postForm(`${path}/finish`, {});
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe(path);

    const finishedBody = await (await fetch(`${base}${path}`)).text();
    expect(finishedBody).toContain('Finished');
    expect(finishedBody).toContain(`${path}/reopen`);

    await postForm(`${path}/reopen`, {});
    expect(store.reading()).toHaveLength(1);
  });

  it('returns home after finishing from the list', async () => {
    const location = await addBook({ title: 'Dune' });
    const path = new URL(location, base).pathname;

    const res = await postForm(`${path}/finish`, {}, { Referer: base + '/' });
    expect(res.headers.get('location')).toBe('/');
  });

  it('saves notes and confirms', async () => {
    const location = await addBook({ title: 'Dune' });
    const path = new URL(location, base).pathname;

    const res = await postForm(`${path}/notes`, { notes: 'Fear is the mind-killer.' });
    expect(res.headers.get('location')).toBe(`${path}?saved=1`);

    const body = await (await fetch(`${base}${path}?saved=1`)).text();
    expect(body).toContain('Notes saved.');
    expect(body).toContain('Fear is the mind-killer.');
  });

  it('404s an unknown book', async () => {
    const res = await fetch(`${base}/books/does-not-exist`);
    expect(res.status).toBe(404);
    expect(await res.text()).toContain('no book at this address');
  });

  it('404s an action on an unknown book', async () => {
    expect((await postForm('/books/nope/finish', {})).status).toBe(404);
    expect((await postForm('/books/nope/notes', { notes: 'x' })).status).toBe(404);
  });

  it('405s a bad method on a book action', async () => {
    const res = await fetch(`${base}/books/whatever/finish`, { redirect: 'manual' });
    expect(res.status).toBe(405);
  });
});

describe('safety', () => {
  it('escapes HTML in book fields', async () => {
    const location = await addBook({
      title: '<script>alert(1)</script>',
      author: '"><img src=x>',
      notes: 'a & b',
    });

    const body = await (await fetch(`${base}${location}`)).text();
    expect(body).not.toContain('<script>alert(1)</script>');
    expect(body).toContain('&lt;script&gt;');
    expect(body).toContain('&quot;&gt;&lt;img');
    expect(body).toContain('a &amp; b');
  });

  it('404s an unknown path', async () => {
    expect((await fetch(`${base}/nonsense`)).status).toBe(404);
  });

  it('treats a trailing slash as the same page', async () => {
    const location = await addBook({ title: 'Dune' });
    expect((await fetch(`${base}${location}/`)).status).toBe(200);
  });
});

